      pattern: external_exports.string().optional().describe('Only tags whose name contains this text, or matches this glob (* and ?), e.g. "v2.*".'),
      versions_only: external_exports.boolean().optional().describe("Only tags that look like versions (v1.2.3, 1.2)."),
      limit: external_exports.number().int().min(1).max(500).optional().describe("Maximum tags. Default 50.")
