server.registerTool(
  "changesets",
  {
    title: "Changesets of a branch",
    description: "Lists what entered a branch, newest first, grouped by integration: merged pull requests and merges with the commits they brought in, and direct commits. Optional range (base) and filters. Read-only.",
    inputSchema: {
      repository: repositoryArg,
      branch: external_exports.string().optional().describe("Branch to describe. Default: the default branch."),
      base: external_exports.string().optional().describe("Only what entered after this ref (tag, branch or commit)."),
      since: external_exports.string().optional().describe("Integration date from, YYYY-MM-DD."),
      until: external_exports.string().optional().describe("Integration date to, YYYY-MM-DD."),
      search: external_exports.string().optional().describe("Text in subject, SHA, branch name or PR title (also inside groups)."),
      author: external_exports.string().optional().describe("Author or integrator name or e-mail."),
      limit: external_exports.number().int().min(1).max(500).optional().describe("Maximum entries. Default 50.")
    },
    annotations: { readOnlyHint: true, openWorldHint: false }
  },
  async (args) => {
    if (!compliance.confirmed) return locked();
    try {
      const repo = await openRepository(args.repository);
      const ref = args.branch ?? await repo.defaultRef() ?? "HEAD";
      const index = await ChangesetIndex.build(repo, { ref, baseRef: args.base });
      const provider = hostingProvider(repo)?.provider;
      if (provider) await enrichIndex(index, provider, void 0, 0, args.limit ?? 50).catch(() => void 0);
      const page = index.query({ since: args.since, until: args.until, text: args.search, author: args.author, hideForwardIntegration: true }, 0, args.limit ?? 50);
      return json2({
        branch: ref,
        base: args.base,
        total: page.total,
        warnings: index.getSummary().warnings.map((w) => w.message),
        entries: page.entries.map((e) => ({
          kind: e.kind,
          date: e.integrationDate.slice(0, 10),
          title: e.kind === "direct" ? e.commit.subject : e.prTitle ?? e.pullRequest?.title ?? e.commit.subject,
          branch: e.branch?.value,
          branchSource: e.branch?.source,
          pr: e.prNumber,
          prUrl: e.pullRequest?.url,
          sha: ChangesetIndex.headShaOf(e).slice(0, 10),
          integrator: e.commit.authorName,
          flags: e.flags.length ? e.flags : void 0,
          commits: e.kind === "direct" ? void 0 : index.memberCommits(e).map((c) => `${c.sha.slice(0, 7)} ${c.subject} (${c.authorName})`)
        }))
      });
    } catch (error62) {
      return failure2(error62);
    }
  }
);
server.registerTool(
  "where_entered",
  {
    title: "Where did a commit enter the branch",
    description: "For a commit SHA: the integration (pull request, merge or direct commit) that brought it into the branch, when, and the first tag that contains it. Read-only.",
    inputSchema: {
      repository: repositoryArg,
      sha: external_exports.string().regex(/^[0-9a-fA-F]{7,64}$/).describe("Commit SHA (at least 7 characters)."),
      branch: external_exports.string().optional().describe("Branch. Default: the default branch.")
    },
    annotations: { readOnlyHint: true, openWorldHint: false }
  },
  async (args) => {
    if (!compliance.confirmed) return locked();
    try {
      const repo = await openRepository(args.repository);
      const ref = args.branch ?? await repo.defaultRef() ?? "HEAD";
      const index = await ChangesetIndex.build(repo, { ref });
      const where = await index.whereEntered(args.sha);
      if (!where) return text(`${args.sha} is not in the history of ${ref}.`);
      const e = where.entry;
      return json2({
        commit: where.sha,
        branch: ref,
        enteredOn: e.integrationDate,
        how: e.kind === "direct" ? "direct commit" : e.kind === "pull-request" ? "rebase-merged pull request" : "merge",
        title: e.prTitle ?? e.commit.subject,
        mergedBranch: e.branch?.value,
        pr: e.prNumber,
        integrator: e.commit.authorName,
        firstTag: where.firstTag ?? null
      });
    } catch (error62) {
      return failure2(error62);
    }
  }
);
